// Enum for the status of the Item's insights
type MonitoringItemStatusCode string

const (
	MonitoringItemStatusCodeAvailable MonitoringItemStatusCode = "AVAILABLE"
	MonitoringItemStatusCodeFailed    MonitoringItemStatusCode = "FAILED"
	MonitoringItemStatusCodePending   MonitoringItemStatusCode = "PENDING"
)

func NewMonitoringItemStatusCodeFromString(s string) (MonitoringItemStatusCode, error) {
	switch s {
	case "AVAILABLE":
		return MonitoringItemStatusCodeAvailable, nil
	case "FAILED":
		return MonitoringItemStatusCodeFailed, nil
	case "PENDING":
		return MonitoringItemStatusCodePending, nil
	}
	var t MonitoringItemStatusCode
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (m MonitoringItemStatusCode) Ptr() *MonitoringItemStatusCode {
	return &m
}

